41	     * <p>更新为不同的值确保 H2/MySQL 不跳过加锁；与替换操作的行更新互斥，
42	     * 保证审核读到的航线版本与点列来自一致状态。</p>
43	     *
44	     * @return 航线当前状态；航线不存在返回 null（更新 0 行）
45	     */
46	    public RoutePo findRouteForUpdate(String routeId) {
47	        int locked = jdbc.update(
48	                "UPDATE route SET touch = touch + 1 WHERE route_id = ?", routeId);
49	        if (locked == 0) {
50	            return null;
51	        }
52	        Integer version = jdbc.queryForObject(
