3	import org.springframework.boot.ApplicationRunner;
4	import org.springframework.context.annotation.Bean;
5	import org.springframework.context.annotation.Configuration;
6	import org.springframework.core.annotation.Order;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	
9	/**
10	 * 初始化全局空域版本单行（初始版本 0）与事务协调锁单行。
11	 * 建表由 schema.sql 完成；启动时先查后插，保证同一内存库内
12	 * 多个 Spring 上下文（如测试）重复初始化时仍然幂等。
13	 */
14	@Configuration
15	public class DataInitializer {
16	
17	    @Bean
18	    @Order(0)
19	    ApplicationRunner initAirspaceMeta(JdbcTemplate jdbc) {
20	        return args -> {
21	            insertIfMissing(jdbc, "airspace_meta",
22	                    "INSERT INTO airspace_meta (id, global_version) VALUES (1, 0)");
23	            insertIfMissing(jdbc, "coord_lock",
24	                    "INSERT INTO coord_lock (id, touched) VALUES (1, 0)");
25	        };
26	    }
27	
28	    private static void insertIfMissing(JdbcTemplate jdbc, String table, String insertSql) {
29	        Integer count = jdbc.queryForObject("SELECT COUNT(*) FROM " + table, Integer.class);
30	        if (count != null && count == 0) {
31	            jdbc.update(insertSql);
32	        }
33	    }
34	}
