402	    void blockedCanBeFixedAndReusedWithSameFlightKey() {
403	        String routeId = createRoute("r-fix");
404	        long zv = createHitZone("z-fix");
405	
406	        // 尚无豁免包 → BLOCKED 快照落库但不锁 flightKey
407	        FlightReviewResultDto blocked = dataOf(review("fk-fix", routeId, NOW));
408	        assertEquals("BLOCKED", blocked.conclusion());
409	        assertEquals(0, count("permit_redeem"));
410	
411	        // 审批人补发覆盖该区域的有效豁免包后，同 flightKey 新 requestId 再审核 → CLEAR
412	        issue("p-fix", routeId, 1, item("z-fix", zv, 3));
413	        MutationResponse cleared = service.flightReview(new FlightReviewRequest(
414	                "fk-fix", routeId, NOW, "req-fix-after"));
415	        assertFalse(cleared.replayed());
416	        FlightReviewResultDto clearDto = dataOf(cleared);
417	        assertEquals("CLEAR", clearDto.conclusion());
418	        assertEquals("p-fix", clearDto.permitKey());
419	        assertEquals(2, remaining("p-fix", "z-fix"));
420	
421	        // 历史包含 BLOCKED 与 CLEAR 两条快照，时间正序，最终审核唯一
422	        List<FlightReviewResultDto> history = service.getFlightHistory("fk-fix");
423	        assertEquals(2, history.size());
424	        assertEquals("BLOCKED", history.get(0).conclusion());
425	        assertEquals("CLEAR", history.get(1).conclusion());
426	        assertEquals(1, jdbc.queryForObject(
427	                "SELECT COUNT(*) FROM flight_review WHERE final_key = 'fk-fix'", Integer.class).intValue());
428	        // CLEAR 之后同 flightKey 已锁定
429	        ApiException again = assertThrows(ApiException.class, () -> review("fk-fix", routeId, NOW));
430	        assertEquals(HttpStatus.CONFLICT, again.status());
431	    }
