570	        issue("p-race1", routeId, 1, item("z-race1", zv, 1));
571	
572	        int n = 2;
573	        CyclicBarrier barrier = new CyclicBarrier(n);
574	        ExecutorService pool = Executors.newFixedThreadPool(n);
575	        try {
576	            List<Future<Object>> futures = new ArrayList<>();
577	            for (int i = 0; i < n; i++) {
578	                String flightKey = "fk-race-" + i;
579	                futures.add(pool.submit(() -> {
580	                    barrier.await(5, TimeUnit.SECONDS);
581	                    try {
582	                        return service.flightReview(new FlightReviewRequest(
583	                                flightKey, routeId, NOW, "req-race-" + flightKey));
584	                    } catch (ApiException ex) {
585	                        return ex;
586	                    }
587	                }));
588	            }
589	            int clear = 0;
590	            int blocked = 0;
591	            for (Future<Object> f : futures) {
592	                Object outcome = f.get(20, TimeUnit.SECONDS);
593	                assertTrue(outcome instanceof MutationResponse, "两次评估都应正常返回结果");
594	                String conclusion = dataOf((MutationResponse) outcome).conclusion();
595	                if ("CLEAR".equals(conclusion)) {
596	                    clear++;
597	                } else {
598	                    blocked++;
599	                    assertEquals("EXHAUSTED",
600	                            defectOf(dataOf((MutationResponse) outcome), "z-race1").reason());
601	                }
602	            }
603	            assertEquals(1, clear, "额度仅 1，只能有一次 CLEAR");
604	            assertEquals(1, blocked, "落败审核必须是 BLOCKED(EXHAUSTED) 而非异常");
605	            assertEquals(0, remaining("p-race1", "z-race1"));
606	            assertEquals(1, count("permit_redeem"));
