608	            assertEquals(1, jdbc.queryForObject(
609	                    "SELECT COUNT(*) FROM flight_review WHERE final_key IS NOT NULL", Integer.class).intValue());
610	        } finally {
611	            pool.shutdownNow();
612	        }
613	    }
